(()=>{
'use strict';
const {products,questions,filterProducts,recommend,buildInquiry}=window.SamhoLogic;
const $=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
let cart=[],compare=new Set(),activeFilter='all',finderStep=0,finderAnswers=[null,null,null],finderContext='',customId=0,toastTimer;
const productById=id=>products.find(p=>p.id===id);
function toast(message){const el=$('#toast'),active=$$('dialog[open]').at(-1);(active||document.body).appendChild(el);el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4000);}
const focusOrigins=new WeakMap();
function openDialog(dialog){const origin=document.activeElement;$$('dialog[open]').forEach(d=>d.close());focusOrigins.set(dialog,origin);dialog.showModal();document.body.classList.add('modal-open');if(dialog.id==='menu-dialog')$('.menu-toggle').setAttribute('aria-expanded','true');}
$$('dialog').forEach(dialog=>{dialog.addEventListener('close',()=>{document.body.appendChild($('#toast'));$('#toast').classList.remove('show');if(!document.querySelector('dialog[open]'))document.body.classList.remove('modal-open');if(dialog.id==='menu-dialog')$('.menu-toggle').setAttribute('aria-expanded','false');const origin=focusOrigins.get(dialog);if(origin?.isConnected)origin.focus({preventScroll:true});});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});});
$$('[data-close]').forEach(button=>button.addEventListener('click',()=>button.closest('dialog').close()));
$('.menu-toggle').addEventListener('click',()=>openDialog($('#menu-dialog')));
$$('#menu-dialog nav a').forEach(a=>a.addEventListener('click',()=>$('#menu-dialog').close()));
let scrollScheduled=false;
function updateScroll(){const y=window.scrollY,max=document.documentElement.scrollHeight-window.innerHeight;$('.reading-progress').style.transform=`scaleX(${max>0?Math.min(1,y/max):0})`;$('#header').classList.toggle('scrolled',y>100);$('.floating-tools').classList.toggle('visible',y>window.innerHeight*.7);scrollScheduled=false;}
window.addEventListener('scroll',()=>{if(!scrollScheduled){scrollScheduled=true;requestAnimationFrame(updateScroll);}},{passive:true});window.addEventListener('resize',updateScroll);updateScroll();
if('IntersectionObserver'in window){document.body.classList.add('js-ready');const revealObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('in-view');revealObserver.unobserve(entry.target);}}),{threshold:.12});$$('.reveal').forEach(el=>revealObserver.observe(el));const navObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){$$('.desktop-nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+entry.target.id));}}),{rootMargin:'-20% 0px -55% 0px'});['about','products','industries','finder'].forEach(id=>navObserver.observe(document.getElementById(id)));}
const slides=[{src:'/designs/v2/assets/hero.webp',alt:'스테인리스 볼 베어링의 정교한 금속 표면',subtitle:'산업의 움직임에, 정밀함을 더하다.',description:'작은 베어링 하나에서 시작되는 더 큰 가능성.\n삼호엔지니어링이 함께합니다.'},{src:'/designs/v2/assets/precision.webp',alt:'정밀 금속 가공을 표현한 산업 콘셉트 이미지',subtitle:'움직임의 완성도는, 작은 디테일에서.',description:'규격, 하중, 환경을 세심하게 살펴봅니다.\n정밀함을 향한 삼호엔지니어링의 기준입니다.'}];
$$('[data-slide]').forEach(button=>button.addEventListener('click',()=>{const slide=slides[Number(button.dataset.slide)];$('#hero-image').src=slide.src;$('#hero-image').alt=slide.alt;$('#hero-subtitle').textContent=slide.subtitle;$('#hero-description').replaceChildren(...slide.description.split('\n').flatMap((line,i)=>i?[document.createElement('br'),document.createTextNode(line)]:[document.createTextNode(line)]));$$('[data-slide]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});}));
const motion=$('.motion-toggle');if(reduced){$('.hero').classList.add('motion-paused');motion.hidden=true;}else motion.addEventListener('click',()=>{const paused=$('.hero').classList.toggle('motion-paused');motion.textContent=paused?'▷':'Ⅱ';motion.setAttribute('aria-label',paused?'배경 움직임 재생':'배경 움직임 일시정지');motion.setAttribute('aria-pressed',String(paused));});
function crop(product){return `<span class="product-crop ${product.id}"><img src="/designs/v2/assets/products.webp" alt="${product.title} 형태의 콘셉트 이미지" width="1536" height="1024" loading="lazy"></span>`;}
function renderCatalog(){const result=filterProducts($('#product-search').value,activeFilter);$('#product-grid').innerHTML=result.map(p=>`<article class="product-card"><div class="product-card-top"><span class="product-id">COLLECTION / ${p.no}</span><label class="compare-check"><input type="checkbox" data-compare="${p.id}" ${compare.has(p.id)?'checked':''} aria-label="${p.title} 비교 선택">비교</label></div><button class="product-image-button" data-detail="${p.id}" aria-label="${p.title} 상세 보기">${crop(p)}</button><div class="product-card-body"><p class="product-en">${p.english}</p><h3 class="product-title">${p.title}</h3><p class="product-description">${p.short}</p><div class="product-tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="product-card-actions"><button class="detail-button" data-detail="${p.id}">제품 자세히 보기 <span aria-hidden="true">↗</span></button><button class="add-button ${cart.some(x=>x.id===p.id)?'added':''}" data-add="${p.id}" aria-label="${p.title} 견적 요청서에 담기">${cart.some(x=>x.id===p.id)?'✓':'+'}</button></div></div></article>`).join('');$('#product-empty').hidden=!!result.length;$('#search-status').textContent=`${result.length}개의 베어링 유형이 표시됩니다.`;}
function updateCompare(){const count=compare.size;$$('.compare-count').forEach(el=>el.textContent=count);$('#compare-open').disabled=count<2;$('#compare-open').title=count<2?'비교할 제품을 2개 이상 선택하세요.':'선택한 제품 비교';}
$$('[data-filter]').forEach(button=>button.addEventListener('click',()=>{activeFilter=button.dataset.filter;$$('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});renderCatalog();}));
$('#product-search').addEventListener('input',renderCatalog);$('#search-reset').addEventListener('click',()=>{$('#product-search').value='';$('[data-filter="all"]').click();$('#product-search').focus();});
$('#product-grid').addEventListener('change',e=>{const input=e.target.closest('[data-compare]');if(input){if(input.checked)compare.add(input.dataset.compare);else compare.delete(input.dataset.compare);updateCompare();}});
function showDetail(id){const p=productById(id);if(!p)return;$('#product-detail').innerHTML=`<div class="detail-layout"><div class="detail-visual">${crop(p)}<span>제품 이해를 위한 콘셉트 이미지입니다.</span></div><div class="detail-copy"><p class="product-en">${p.english}</p><h2 id="detail-title">${p.title}</h2><p>${p.description}</p><dl><div><dt>전동체 구조</dt><dd>${p.element}</dd></div><div><dt>하중 특성</dt><dd>${p.load}</dd></div><div><dt>적용 예시</dt><dd>${p.application}</dd></div><div><dt>선정 시 확인</dt><dd>${p.check}</dd></div></dl><button class="button button-dark" data-add="${p.id}">견적 요청서에 담기 <span aria-hidden="true">+</span></button><p class="micro-note">형식에 대한 일반 안내입니다. 구체적인 품번, 규격, 취급 여부는 별도 확인이 필요합니다.</p></div></div>`;openDialog($('#product-dialog'));}
$('#compare-open').addEventListener('click',()=>{const selected=products.filter(p=>compare.has(p.id));const rows=[['전동체 구조','element'],['하중 특성','load'],['적용 예시','application'],['선정 시 확인','check']];$('#compare-content').innerHTML=`<div class="table-scroll" tabindex="0" aria-label="제품 비교 표, 작은 화면에서는 가로로 스크롤하세요"><table class="compare-table"><thead><tr><th scope="col">비교 항목</th>${selected.map(p=>`<th scope="col"><span>${p.no} / COLLECTION</span>${p.title}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,key])=>`<tr><th scope="row">${label}</th>${selected.map(p=>`<td>${p[key]}</td>`).join('')}</tr>`).join('')}<tr><th scope="row">요청서</th>${selected.map(p=>`<td><button class="button button-outline" data-add="${p.id}">품목 담기 <span>+</span></button></td>`).join('')}</tr></tbody></table></div><p class="micro-note">일반적인 유형 비교입니다. 동일 유형에서도 품번과 설계에 따라 특성이 다릅니다.</p>`;openDialog($('#compare-dialog'));});
function invalidateOutput(){$('#quote-output').hidden=true;$('#quote-error').textContent='';}
function updateCartCount(){$$('.quote-count').forEach(el=>el.textContent=cart.length);}
function addProduct(id){const p=productById(id);if(!p)return;if(cart.some(x=>x.id===id)){toast('이미 견적 요청서에 담긴 품목입니다.');return;}if(cart.length>=20){toast('요청서에는 최대 20개 품목을 담을 수 있습니다.');return;}cart.push({key:id,id,title:p.title,qty:1,custom:false});updateCartCount();renderQuoteItems();renderCatalog();invalidateOutput();toast(p.title+'을(를) 견적 요청서에 담았습니다.');}
function renderQuoteItems(){$('#quote-items').innerHTML=cart.length?cart.map(item=>`<div class="quote-item" data-key="${item.key}">${item.custom?`<label>품번 또는 제품명<input class="custom-name" data-item-name value="${escape(item.title)}" maxlength="150" placeholder="품번 또는 제품명"></label>`:`<p class="quote-item-name">${escape(item.title)}<small>${productById(item.id)?.english||''}</small></p>`}<label>수량<input type="number" min="1" max="1000000" step="1" inputmode="numeric" data-item-qty value="${item.qty}" aria-label="${escape(item.title||'직접 입력 품목')} 수량"></label><button class="remove-item" data-remove="${item.key}" aria-label="${escape(item.title||'직접 입력 품목')} 삭제">×</button></div>`).join(''):'<div class="quote-empty">제품 탐색에서 품목을 담거나<br>아래에서 필요한 품번을 직접 입력해 주세요.</div>';}
function openQuote(){renderQuoteItems();openDialog($('#quote-dialog'));}
$$('[data-open-quote]').forEach(b=>b.addEventListener('click',openQuote));
document.addEventListener('click',e=>{const detail=e.target.closest('[data-detail]');if(detail){showDetail(detail.dataset.detail);return;}const add=e.target.closest('[data-add]');if(add){addProduct(add.dataset.add);return;}const remove=e.target.closest('[data-remove]');if(remove){cart=cart.filter(x=>x.key!==remove.dataset.remove);renderQuoteItems();renderCatalog();updateCartCount();invalidateOutput();}});
$('#add-custom').addEventListener('click',()=>{if(cart.length>=20){toast('요청서에는 최대 20개 품목을 담을 수 있습니다.');return;}const key='custom-'+(++customId);cart.push({key,id:null,title:'',qty:1,custom:true});renderQuoteItems();updateCartCount();invalidateOutput();$(`[data-key="${key}"] [data-item-name]`).focus();});
$('#quote-items').addEventListener('input',e=>{const row=e.target.closest('[data-key]');if(!row)return;const item=cart.find(x=>x.key===row.dataset.key);if(e.target.matches('[data-item-name]'))item.title=e.target.value;if(e.target.matches('[data-item-qty]'))item.qty=e.target.value;invalidateOutput();});
$('#quote-form').addEventListener('input',invalidateOutput);
$('#quote-form').addEventListener('submit',e=>{e.preventDefault();try{const fields=Object.fromEntries(new FormData(e.target));const text=buildInquiry(cart,fields,finderContext,new Date().toLocaleDateString('ko-KR'));$('#quote-text').value=text;$('#quote-output').hidden=false;$('#quote-error').textContent='';$('#quote-output').scrollIntoView({behavior:reduced?'auto':'smooth',block:'nearest'});toast('요청서를 만들었습니다. 복사하거나 파일로 저장해 주세요.');}catch(error){$('#quote-error').textContent=error.message;}});
function download(name,text){const blob=new Blob(['\uFEFF'+text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copy(text,fallback){try{await navigator.clipboard.writeText(text);toast('복사했습니다. 원하는 곳에 붙여넣어 주세요.');}catch{if(fallback){fallback.focus();fallback.select();toast('자동 복사가 제한되어 있습니다. 선택된 내용을 직접 복사해 주세요.');}else{download('삼호엔지니어링_문의양식.txt',text);toast('자동 복사가 제한되어 문의 양식을 파일로 저장했습니다.');}}}
$('#copy-quote').addEventListener('click',()=>copy($('#quote-text').value,$('#quote-text')));
$('#download-quote').addEventListener('click',()=>{download('삼호엔지니어링_견적요청서.txt',$('#quote-text').value);toast('견적 요청서를 저장했습니다.');});
const blank='[삼호엔지니어링 제품 문의]\n제품 품번: \n규격(내경 × 외경 × 폭): \n사용 장비: \n회전 속도 및 사용 환경: \n필요 수량: \n희망 납기: \n회사 / 담당자: \n회신 연락처: ';
$('#copy-blank').addEventListener('click',()=>copy(blank));
$('#download-checklist').addEventListener('click',()=>{download('삼호엔지니어링_베어링상담_체크리스트.txt','삼호엔지니어링 | 베어링 상담 체크리스트\n\n□ 기존 품번과 측면 각인 확인\n□ 내경·외경·폭 및 장착 공간 확인\n□ 장비명과 제조사 요구 조건 확인\n□ 하중 크기·방향과 회전 속도 확인\n□ 온도·분진·수분 노출 조건 확인\n□ 윤활 방식 및 내부 틈새·씰 형식 확인\n□ 필요한 수량과 희망 납기 정리\n□ 담당자와 회신 연락처 준비\n\n최종 선정은 제품 및 장비의 기술 자료에 따라 별도 검토해야 합니다.');toast('상담 체크리스트를 저장했습니다.');});
function renderFinder(){const content=$('#finder-content');$('#finder-number').textContent=String(Math.min(finderStep+1,3)).padStart(2,'0');$$('.finder-progress>span').forEach((el,i)=>el.classList.toggle('current',i===Math.min(finderStep,2)));if(finderStep<3){const q=questions[finderStep];content.innerHTML=`<h3 class="finder-question" id="finder-question">${q.title}</h3><p class="finder-help">${q.help}</p><div class="finder-options" role="radiogroup" aria-labelledby="finder-question">${q.options.map(o=>`<label class="finder-option"><input type="radio" name="finder-option" value="${o.value}" ${finderAnswers[finderStep]===o.value?'checked':''}><span><strong>${o.title}</strong><small>${o.sub}</small></span></label>`).join('')}</div><div class="finder-actions"><button class="text-button" data-finder-back ${finderStep===0?'disabled':''}>← 이전 질문</button><button class="button button-dark" data-finder-next ${finderAnswers[finderStep]?'':'disabled'}>${finderStep===2?'결과 확인':'다음 질문'} <span aria-hidden="true">→</span></button></div>`;}else{const r=recommend(finderAnswers);content.innerHTML=`<div class="finder-result"><p class="finder-result-label">YOUR STARTING POINT</p><h3 tabindex="-1" id="finder-result-title">${r.title}</h3><p>${r.reason}</p><div class="result-conditions">${r.labels.map(l=>`<span>${l}</span>`).join('')}</div><div class="result-products">${r.ids.map(id=>`<button data-detail="${id}">${productById(id).title}<span>↗</span></button>`).join('')}</div><p class="micro-note" style="margin-top:18px">${r.envNote}</p><div class="result-actions"><button class="button button-dark" data-finder-quote>조건을 요청서에 넣기 <span>↗</span></button><button class="text-button" data-finder-reset>다시 시작 ↺</button></div></div>`;}}
$('#finder-content').addEventListener('change',e=>{if(e.target.name==='finder-option'){finderAnswers[finderStep]=e.target.value;$('[data-finder-next]').disabled=false;}});
$('#finder-content').addEventListener('click',e=>{if(e.target.closest('[data-finder-next]')&&finderAnswers[finderStep]){finderStep++;renderFinder();const heading=$('#finder-question')||$('#finder-result-title');heading.tabIndex=-1;heading.focus({preventScroll:true});}else if(e.target.closest('[data-finder-back]')&&finderStep>0){finderStep--;renderFinder();$('#finder-question').tabIndex=-1;$('#finder-question').focus({preventScroll:true});}else if(e.target.closest('[data-finder-reset]')){finderStep=0;finderAnswers=[null,null,null];renderFinder();$('#finder-question').tabIndex=-1;$('#finder-question').focus({preventScroll:true});}else if(e.target.closest('[data-finder-quote]')){const r=recommend(finderAnswers);finderContext=r.labels.join(' / ')+'\n'+r.envNote;$('#quote-context').textContent='선정 도우미에서 정리한 조건: '+r.labels.join(' · ');$('#quote-context').hidden=false;invalidateOutput();openQuote();toast('사용 조건을 요청서에 넣었습니다. 문의할 품목을 추가해 주세요.');}});
$('#year').textContent=new Date().getFullYear();renderCatalog();updateCompare();renderQuoteItems();renderFinder();
})();
